package com.lianxibu.site.config;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.JdbcReportSchedulePages;
import com.lianxibu.site.service.jobs.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.transaction.PlatformTransactionManager;
class ReportPreparationRuntimeConfigurationTest {
 static final List<String> FLAGS=List.of("site.browser.enabled","site.content.enabled","site.articles.enabled","site.sources.enabled","site.execution.enabled","site.collector.enabled","site.sources.day-roster.enabled","site.execution.report-preparation.enabled","site.execution.report-runtime.enabled");
 final DataSource source=mock(DataSource.class);final PlatformTransactionManager tx=mock(PlatformTransactionManager.class);final ReportPreparationService preparation=mock(ReportPreparationService.class);final ReportNoUpdateProofService noUpdates=mock(ReportNoUpdateProofService.class);final OperationalInputGate gate=mock(OperationalInputGate.class);final ScheduledExecutorService executor=mock(ScheduledExecutorService.class);
 ApplicationContextRunner base(){return new ApplicationContextRunner().withUserConfiguration(ReportPreparationRuntimeConfiguration.class);}
 ApplicationContextRunner enabled(){return base().withPropertyValues(FLAGS.stream().map(f->f+"=true").toArray(String[]::new));}
 ApplicationContextRunner ports(ApplicationContextRunner c,int missing){if(missing!=0)c=c.withBean(DataSource.class,()->source);if(missing!=1)c=c.withBean(PlatformTransactionManager.class,()->tx);if(missing!=2)c=c.withBean(ReportPreparationService.class,()->preparation);if(missing!=3)c=c.withBean(ReportNoUpdateProofService.class,()->noUpdates);if(missing!=4)c=c.withBean(OperationalInputGate.class,()->gate);return c.withBean("reportPreparationExecutor",ScheduledExecutorService.class,()->executor);}
 @Test void DefaultAndEveryMissingFlagCreateNoThreadCycleOrNativePages(){base().run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(ScheduledExecutorService.class).isEmpty());assertTrue(c.getBeansOfType(ReportPreparationCycle.class).isEmpty());});for(String flag:FLAGS)base().withPropertyValues(FLAGS.stream().filter(f->!f.equals(flag)).map(f->f+"=true").toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(JdbcReportSchedulePages.class).isEmpty());assertTrue(c.getBeansOfType(ReportPreparationRuntimeConfiguration.Loop.class).isEmpty());});}
 @Test void ActualNativeCycleIsUniqueColdAndEnabledSchedulerUsesOnlyItsOwnExecutor(){var future=mock(ScheduledFuture.class);when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS))).thenReturn(future);ports(enabled(),-1).run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(JdbcReportSchedulePages.class).size());assertEquals(1,c.getBeansOfType(ReportPreparationCycle.class).size());assertTrue(c.getBean(ReportPreparationRuntimeConfiguration.Loop.class).isRunning());verifyNoInteractions(source,tx,preparation,noUpdates,gate);});verify(future).cancel(false);}
 @Test void EveryMissingRequiredNativePortAndOutOfBoundsIntervalRejectStartup(){when(executor.scheduleWithFixedDelay(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.SECONDS))).thenReturn(mock(ScheduledFuture.class));for(int missing=0;missing<5;missing++)ports(enabled(),missing).run(c->assertNotNull(c.getStartupFailure()));for(String interval:List.of("0","301"))ports(enabled().withPropertyValues("site.execution.report-runtime.interval-seconds="+interval),-1).run(c->assertNotNull(c.getStartupFailure()));verifyNoInteractions(source,tx,preparation,noUpdates,gate);}
 @Test void ExecutorIsSingleLazyDaemonAndCancelsDeferredWork(){var ex=(ScheduledThreadPoolExecutor)new ReportPreparationRuntimeConfiguration().reportPreparationExecutor();try{assertEquals(1,ex.getCorePoolSize());assertEquals(0,ex.getPoolSize());assertTrue(ex.getRemoveOnCancelPolicy());assertFalse(ex.getExecuteExistingDelayedTasksAfterShutdownPolicy());assertFalse(ex.getContinueExistingPeriodicTasksAfterShutdownPolicy());assertTrue(ex.getThreadFactory().newThread(()->{}).isDaemon());}finally{ex.shutdownNow();}}
 @Test void RecoveryResetsOnSuccessAndStoppedTicksCannotPrepare(){var tick=new AtomicReference<Runnable>();var future=mock(ScheduledFuture.class);var cycle=mock(ReportPreparationCycle.class);when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(7L),eq(7L),eq(TimeUnit.SECONDS))).thenAnswer(i->{tick.set(i.getArgument(0));return future;});when(cycle.run(any())).thenReturn(ReportPreparationCycle.Outcome.RECOVERY_REQUIRED,ReportPreparationCycle.Outcome.BUSY,ReportPreparationCycle.Outcome.PREPARED);var loop=new ReportPreparationRuntimeConfiguration.Loop(cycle,executor,7);verifyNoInteractions(executor);loop.start();loop.start();tick.get().run();assertTrue(loop.hasFailure());tick.get().run();assertTrue(loop.hasFailure());tick.get().run();assertFalse(loop.hasFailure());loop.stop();tick.get().run();verify(cycle,times(3)).run(any());verify(future).cancel(false);}
 @Test void ConcurrentStopWaitsForInflightTickAndPreventsOverlapAndRestart()throws Exception{var tick=new AtomicReference<Runnable>();var cycle=mock(ReportPreparationCycle.class);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var stopped=new CountDownLatch(1);when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS))).thenAnswer(i->{tick.set(i.getArgument(0));return mock(ScheduledFuture.class);});when(cycle.run(any())).thenAnswer(i->{var running=i.getArgument(0,java.util.function.BooleanSupplier.class);assertTrue(running.getAsBoolean());entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));assertFalse(running.getAsBoolean());return ReportPreparationCycle.Outcome.IDLE;});var loop=new ReportPreparationRuntimeConfiguration.Loop(cycle,executor,1);try(var runner=Executors.newSingleThreadExecutor()){loop.start();var active=runner.submit(()->tick.get().run());try{assertTrue(entered.await(5,TimeUnit.SECONDS));tick.get().run();verify(cycle,times(1)).run(any());loop.stop(stopped::countDown);assertEquals(1,stopped.getCount());assertThrows(RuntimeException.class,loop::start);}finally{release.countDown();}active.get(5,TimeUnit.SECONDS);assertTrue(stopped.await(1,TimeUnit.SECONDS));}tick.get().run();verify(cycle,times(1)).run(any());when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS))).thenThrow(new RejectedExecutionException());assertThrows(RejectedExecutionException.class,loop::start);assertFalse(loop.isRunning());}
}
